const express = require('express');
const axios = require('axios');
const dns = require('dns');
const url = require('url');

const app = express();
app.use(express.json());

// Internal metadata service for cloud instance configuration
const INTERNAL_SERVICES = {
  'metadata': 'http://169.254.169.254/latest/meta-data/',
  'config': 'http://10.0.1.50:8080/internal/config',
  'health': 'http://10.0.1.50:8080/internal/health'
};

// Webhook notification service - allows users to register callback URLs
// for event notifications from our platform
app.post('/api/webhooks/test', async (req, res) => {
  const { callbackUrl } = req.body;

  if (!callbackUrl) {
    return res.status(400).json({ error: 'callbackUrl is required' });
  }

  try {
    const parsed = url.parse(callbackUrl);

    // Security: block obviously internal IPs at registration time
    const blockedPrefixes = ['10.', '172.16.', '172.17.', '172.18.', '172.19.',
      '172.20.', '172.21.', '172.22.', '172.23.', '172.24.', '172.25.',
      '172.26.', '172.27.', '172.28.', '172.29.', '172.30.', '172.31.',
      '192.168.', '169.254.', '127.'];

    // Resolve hostname to check IP
    const addresses = await new Promise((resolve, reject) => {
      dns.resolve4(parsed.hostname, (err, addrs) => {
        if (err) reject(err);
        else resolve(addrs);
      });
    });

    const firstAddr = addresses[0];
    const isBlocked = blockedPrefixes.some(prefix => firstAddr.startsWith(prefix));

    if (isBlocked) {
      return res.status(403).json({ error: 'Internal addresses are not allowed' });
    }

    // DNS check passed - now make the actual callback request
    // NOTE: Time-of-check to time-of-use gap here allows DNS rebinding
    const response = await axios.get(callbackUrl, {
      timeout: 5000,
      maxRedirects: 0,
      headers: {
        'User-Agent': 'WebhookValidator/1.0',
        'X-Webhook-Test': 'true'
      }
    });

    return res.json({
      success: true,
      statusCode: response.status,
      headers: response.headers,
      body: response.data
    });

  } catch (error) {
    return res.status(502).json({
      success: false,
      error: error.message
    });
  }
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: Date.now() });
});

// Webhook registration (stores for later use)
app.post('/api/webhooks/register', async (req, res) => {
  const { name, url: webhookUrl, events } = req.body;

  if (!name || !webhookUrl || !events) {
    return res.status(400).json({ error: 'name, url, and events are required' });
  }

  // In production this would persist to database
  res.json({
    id: Math.random().toString(36).substr(2, 9),
    name,
    url: webhookUrl,
    events,
    created: new Date().toISOString()
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Webhook service listening on port ${PORT}`);
});
